\begin{tikzpicture}
\begin{axis}[
    width=0.78\textwidth,
    height=0.48\textwidth,
    xmin=-2.2, xmax=2.2,
    ymin=-0.4, ymax=5.0,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={-2,-1,0,1,2},
    ytick={0,1,2,3,4},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    legend style={draw=none, at={(0.03,0.97)}, anchor=north west}
]
\addplot[thick, domain=-2.2:2.2, samples=200] {exp(x)};
\addlegendentry{\(y=e^x\)}
\addplot[thick, dashed, domain=-1.3:1.8, samples=2] {1+x};
\addlegendentry{\(y=1+x\)}
\addplot[only marks, mark=*] coordinates {(0,1)};
\node[fill=white, inner sep=1pt, anchor=south east] at (axis cs:-0.08,1.12) {\((0,1)\)};
\end{axis}
\end{tikzpicture}
